CREATE OR REPLACE FUNCTION pg_temp.must_fail(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF position(expected IN SQLERRM)=0 THEN RAISE EXCEPTION 'Unexpected rejection: %',SQLERRM; END IF; RETURN; END; RAISE EXCEPTION 'Unsafe statement succeeded: %',statement; END $$;
CREATE OR REPLACE FUNCTION pg_temp.assert_true(value boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
