CREATE FUNCTION pg_temp.stage_capture(actor uuid,revision integer,status text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE tasks jsonb; scope jsonb;
BEGIN
 SELECT jsonb_build_object('modules',modules,'furnishing_scope',furnishing_scope,'director',director) INTO scope FROM onboarding_projects WHERE id='00000000-0000-4000-8000-000000000802';
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO tasks FROM onboarding_tasks t WHERE property_id='00000000-0000-4000-8000-000000000801';
 PERFORM record_onboarding_stage_capture('00000000-0000-4000-8000-000000000802',actor,revision,jsonb_build_object('stage','phase1_inspection','actor',actor,'revision',revision+1,'status',status,'observation','Inspection reviewed','evidenceIds','[]'::jsonb),tasks,scope);
END $$;
SELECT pg_temp.stage_capture('00000000-0000-4000-8000-000000000003',0,'awaiting_review');
SELECT pg_temp.stage_capture('00000000-0000-4000-8000-000000000004',1,'complete');
CREATE FUNCTION pg_temp.request() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('snapshot',private.onboarding_handoff_snapshot('00000000-0000-4000-8000-000000000801'),'checklist','[]'::jsonb,'validation','{}'::jsonb,'openTaskIds','[]'::jsonb,'applicableTaskIds',jsonb_build_array('00000000-0000-4000-8000-000000000803'),'carryoverAccepted',false) $$;
SAVEPOINT stale_finance_request;
SELECT set_config('test.request',pg_temp.request()::text,true);
UPDATE approvals SET status='pending' WHERE id='00000000-0000-4000-8000-000000000824';
SELECT pg_temp.must_fail($q$SELECT create_onboarding_handoff('00000000-0000-4000-8000-000000000801','00000000-0000-4000-8000-000000000003','onboarding',current_setting('test.request')::jsonb)$q$,'Readiness changed');
SELECT pg_temp.must_fail($q$SELECT create_onboarding_handoff('00000000-0000-4000-8000-000000000801','00000000-0000-4000-8000-000000000003','onboarding',pg_temp.request())$q$,'Financial readiness blocked');
ROLLBACK TO stale_finance_request;
SELECT set_config('test.request',pg_temp.request()::text,true);
SET LOCAL ROLE service_role;
SELECT set_config('test.handoff',create_onboarding_handoff('00000000-0000-4000-8000-000000000801','00000000-0000-4000-8000-000000000003','onboarding',current_setting('test.request')::jsonb)::text,true);
SELECT pg_temp.must_fail($q$UPDATE properties SET lifecycle_status='onboarding' WHERE id='00000000-0000-4000-8000-000000000801'$q$,'handoff review chain');
SELECT pg_temp.must_fail($q$UPDATE properties SET onboarding_stage='phase6_handoff' WHERE id='00000000-0000-4000-8000-000000000801'$q$,'handoff review chain');
SELECT pg_temp.must_fail($q$UPDATE onboarding_tasks SET due_on=current_date WHERE id='00000000-0000-4000-8000-000000000803'$q$,'Return the handoff');
RESET ROLE;
SAVEPOINT changed_field_review;
UPDATE work_orders SET closed_at=NULL WHERE id='00000000-0000-4000-8000-000000000830';
SELECT set_config('test.actor','00000000-0000-4000-8000-000000000004',true);
SELECT pg_temp.must_fail($q$SELECT review_onboarding_handoff(current_setting('test.handoff')::uuid,'kati_review','accepted')$q$,'submitted readiness record changed');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM handoff_reviews WHERE handoff_id=current_setting('test.handoff')::uuid),'Changed independent work cannot leave a partial review');
ROLLBACK TO changed_field_review;
UPDATE financial_requests SET status='sent_to_accounting',invoice_amount=500 WHERE id='00000000-0000-4000-8000-000000000820';
SELECT set_config('test.actor','00000000-0000-4000-8000-000000000004',true);
SELECT review_onboarding_handoff(current_setting('test.handoff')::uuid,'kati_review','accepted');
SELECT set_config('test.actor','00000000-0000-4000-8000-000000000008',true);
SELECT review_onboarding_handoff(current_setting('test.handoff')::uuid,'micah_review','accepted');
SELECT set_config('test.actor','00000000-0000-4000-8000-000000000009',true);
SELECT review_onboarding_handoff(current_setting('test.handoff')::uuid,'operations_acceptance','accepted');
UPDATE financial_requests SET status='settled' WHERE id='00000000-0000-4000-8000-000000000820';
SELECT review_onboarding_handoff(current_setting('test.handoff')::uuid,'live_confirmation','accepted');
SELECT pg_temp.assert_true((SELECT lifecycle_status='active_operations' FROM properties WHERE id='00000000-0000-4000-8000-000000000801'),'Accounting progress cannot prevent separate Live confirmation');
ROLLBACK;
